import{_ as t,c as o,o as a,am as i}from"./chunks/framework.83COwwOK.js";const g=JSON.parse('{"title":"Pogget","description":"","frontmatter":{"prev":false,"next":{"text":"Component grouping","link":"/en/docs/pogget/group"}},"headers":[],"relativePath":"en/docs/pogget/index.md","filePath":"en/docs/pogget/index.md"}'),r={name:"en/docs/pogget/index.md"};function n(s,e,l,h,c,d){return a(),o("div",null,e[0]||(e[0]=[i('<h1 id="pogget" tabindex="-1">Pogget <a class="header-anchor" href="#pogget" aria-label="Permalink to &quot;Pogget&quot;">​</a></h1><blockquote><p>A lightweight file interaction efficiency tool that is completely free and supported by every user. To protect your information security, if you download it through the website, please make sure the download source is from the official website <a href="https://pogget.vilinko.com" target="_blank" rel="noreferrer">https://pogget.vilinko.com</a>. You are welcome to participate in improving the documentation <a href="https://github.com/VilinkoStudio/docs.vilinko.com/edit/source/docs/pogget" target="_blank" rel="noreferrer">here</a>!</p></blockquote><p><img src="https://img.shields.io/badge/Platform-Windows-lightgrey.svg" alt="Platform"><img src="https://img.shields.io/badge/Language-C++-00599C.svg" alt="C++"></p><h2 id="✨-learn-more" tabindex="-1">✨ Learn more <a class="header-anchor" href="#✨-learn-more" aria-label="Permalink to &quot;✨ Learn more&quot;">​</a></h2><ul><li><strong>📦 Mapping Storage Box</strong> No file transfers. Just establish connections. Drag commonly used files hidden in various parts of the computer into it, and they can be opened directly on the desktop. No extra space is occupied, and you can clear them anytime after use, making it light and hassle-free.</li><li><strong>📦 Regular Storage Box</strong> The small drawer on the desk is prepared for daily work. Files will be moved into it, where you can rename, delete, or archive them. Put all the materials you need to handle today in here for peace of mind.</li><li><strong>📦 Target Storage Box</strong> Similar to a regular storage box, but it directly binds the storage box with the existing folders on the hard drive. Whatever you drag and organize on the storage box, the real folders will change accordingly. No need to switch windows back and forth, with two-way synchronization, what you see is what you get.</li><li><strong>🧲 Magnetic Access Window</strong> When the open/save dialog box is triggered, it immediately docks next to the window. The content of the access window is identical and interchangeable with the storage box. When you&#39;re unsure or need to temporarily store a file, you can create a hidden storage box as a temporary workspace for easy access.</li><li><strong>⚡ Quick Panel</strong> The contents of all storage boxes will appear here. You can quickly press a shortcut key to trigger them when needed, eliminating the hassle of searching for files. Additionally, you can split the panel to manage files like a browser.</li></ul><h2 id="✨-how-to-start" tabindex="-1">✨ How to Start <a class="header-anchor" href="#✨-how-to-start" aria-label="Permalink to &quot;✨ How to Start&quot;">​</a></h2><p>This project does not require complicated installation steps.</p><ol><li>Extract the file (Pogget.exe) to any directory you like, or place it directly on the desktop. README.md is the project description and does not need to be placed.</li><li>Open the app directly. If the system prompts that the dll is missing, you can download the patch from <a href="https://aka.ms/vc14/vc_redist.x64.exe" target="_blank" rel="noreferrer">https://aka.ms/vc14/vc_redist.x64.exe</a>.</li></ol><h2 id="🗑️-how-to-uninstall" tabindex="-1">🗑️ How to Uninstall <a class="header-anchor" href="#🗑️-how-to-uninstall" aria-label="Permalink to &quot;🗑️ How to Uninstall&quot;">​</a></h2><p>This application adheres to the green application principle and will not write any bloated information to your system. The uninstallation process is very simple:</p><ol><li>Delete all files (user basic data, optional) in Settings -&gt; View User Data.</li><li>Right-click the small icon on the taskbar to exit the program.</li><li><strong>Simply delete the program files.</strong></li></ol><h2 id="❤️-support-and-participation" tabindex="-1">❤️ Support and Participation <a class="header-anchor" href="#❤️-support-and-participation" aria-label="Permalink to &quot;❤️ Support and Participation&quot;">​</a></h2><p>Your comment, suggestion, or sponsorship will become part of Pogget&#39;s journey. If you are able, you can support the project on <a href="https://afdian.com/a/EnderMo" target="_blank" rel="noreferrer">Aidian</a>. You can also learn more about ways to participate on the <a href="https://pogget.vilinko.com/#together" target="_blank" rel="noreferrer">official website</a>.</p>',13)]))}const u=t(r,[["render",n]]);export{g as __pageData,u as default};
